int vc4_get_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    u32 bin_size = exec->cmdlist_arg->bin_size;
    u32 shader_records_size = exec->cmdlist_arg->shader_records_size;
    u32 uniforms_size = exec->cmdlist_arg->uniforms_size;
    void *bin_map, *shader_records_map, *uniforms_map;
    struct drm_gem_cma_object *bo;
    int ret;

    if (bin_size > 0x100000 || shader_records_size > 0x100000 ||
        uniforms_size > 0x100000)
        return -EINVAL;

    bin_map = kmalloc(bin_size, GFP_KERNEL);
    if (!bin_map)
        return -ENOMEM;

    ret = copy_from_user(bin_map, exec->cmdlist_arg->bin_ptr, bin_size);
    if (ret) {
        kfree(bin_map);
        return -EFAULT;
    }

    shader_records_map = kmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records_map) {
        kfree(bin_map);
        return -ENOMEM;
    }

    ret = copy_from_user(shader_records_map, exec->cmdlist_arg->shader_records_ptr, shader_records_size);
    if (ret) {
        kfree(bin_map);
        kfree(shader_records_map);
        return -EFAULT;
    }

    uniforms_map = kmalloc(uniforms_size, GFP_KERNEL);
    if (!uniforms_map) {
        kfree(bin_map);
        kfree(shader_records_map);
        return -ENOMEM;
    }

    ret = copy_from_user(uniforms_map, exec->cmdlist_arg->uniforms_ptr, uniforms_size);
    if (ret) {
        kfree(bin_map);
        kfree(shader_records_map);
        kfree(uniforms_map);
        return -EFAULT;
    }

    bo = drm_gem_cma_create(dev, bin_size + shader_records_size + uniforms_size);
    if (!bo) {
        kfree(bin_map);
        kfree(shader_records_map);
        kfree(uniforms_map);
        return -ENOMEM;
    }

    memcpy(bo->vaddr, bin_map, bin_size);
    memcpy(bo->vaddr + bin_size, shader_records_map, shader_records_size);
    memcpy(bo->vaddr + bin_size + shader_records_size, uniforms_map, uniforms_size);

    exec->bo = &bo->base;

    kfree(bin_map);
    kfree(shader_records_map);
    kfree(uniforms_map);

    return 0;
}

int vc4_prepare_binning(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_exec_state *state = &exec->state;
    int ret;
    u32 *cmd, *shader_records;
    size_t cmd_size, shader_size;
    struct drm_gem_cma_object *obj;

    if (exec->bo_count > 0)
        return -EINVAL;

    cmd_size = exec->binning.command_list_size;
    shader_size = exec->binning.shader_record_size;

    if (cmd_size > VC4_MAX_BINNING_COMMAND_SIZE ||
        shader_size > VC4_MAX_SHADER_RECORD_SIZE)
        return -EINVAL;

    cmd = kmalloc(cmd_size, GFP_KERNEL);
    if (!cmd)
        return -ENOMEM;

    shader_records = kmalloc(shader_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto free_cmd;
    }

    if (copy_from_user(cmd, u64_to_user_ptr(exec->binning.command_list), cmd_size)) {
        ret = -EFAULT;
        goto free_shader;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->binning.shader_record), shader_size)) {
        ret = -EFAULT;
        goto free_shader;
    }

    ret = vc4_validate_command_list(dev, cmd, cmd_size);
    if (ret)
        goto free_shader;

    ret = vc4_validate_shader_records(dev, shader_records, shader_size);
    if (ret)
        goto free_shader;

    obj = vc4_bo_create(dev, cmd_size + shader_size, 0);
    if (!obj) {
        ret = -ENOMEM;
        goto free_shader;
    }

    memcpy(obj->vaddr, cmd, cmd_size);
    memcpy(obj->vaddr + cmd_size, shader_records, shader_size);

    exec->bo = &obj->base;
    exec->bo_count = 1;

    ret = vc4_wait_for_render_complete(dev);
    if (ret)
        goto unref_bo;

    kfree(cmd);
    kfree(shader_records);

    return 0;

unref_bo:
    drm_gem_object_put_unlocked(exec->bo);
    exec->bo = NULL;
free_shader:
    kfree(shader_records);
free_cmd:
    kfree(cmd);
    return ret;
}

int vc4_prepare_binning(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    void *cl_vaddr;
    int ret;

    if (!exec->binning_cl || !exec->shader_records || !exec->uniforms)
        return -EINVAL;

    ret = vc4_cl_check_offsets(exec->binning_cl, exec->shader_records,
                                exec->uniforms, exec->cl_size,
                                exec->shader_records_size,
                                exec->uniforms_size);
    if (ret)
        return ret;

    bo = vc4_bo_create(dev, exec->cl_size + exec->shader_records_size +
                          exec->uniforms_size,
                       0, VC4_BO_TYPE_SHADER);
    if (IS_ERR(bo))
        return PTR_ERR(bo);

    cl_vaddr = vc4_bo_map(bo);
    if (!cl_vaddr) {
        ret = -ENOMEM;
        goto err_free_bo;
    }

    if (copy_from_user(cl_vaddr, exec->binning_cl, exec->cl_size) ||
        copy_from_user(cl_vaddr + exec->cl_size, exec->shader_records,
                       exec->shader_records_size) ||
        copy_from_user(cl_vaddr + exec->cl_size + exec->shader_records_size,
                       exec->uniforms, exec->uniforms_size)) {
        ret = -EFAULT;
        goto err_unmap;
    }

    exec->bin_bo = bo;
    exec->cl_vaddr = cl_vaddr;

    ret = vc4_wait_for_render_complete(dev);
    if (ret)
        goto err_unmap;

    return 0;

err_unmap:
    vc4_bo_unmap(bo);
err_free_bo:
    vc4_bo_unreference(bo);
    return ret;
}

int vc4_prepare_binning_command(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    unsigned int binning_offset = 0;
    unsigned int shader_records_offset;
    unsigned int uniforms_offset;
    struct drm_gem_cma_object *bo;
    void *binning_cmd_list;
    void *shader_records;
    void *uniforms;

    binning_offset = exec->binning_cmd_size;
    shader_records_offset = binning_offset + exec->shader_record_size;
    uniforms_offset = shader_records_offset + exec->uniform_size;

    if (uniforms_offset > 0x100000) {
        return -EINVAL;
    }

    binning_cmd_list = kmalloc(exec->binning_cmd_size, GFP_KERNEL);
    if (!binning_cmd_list) {
        return -ENOMEM;
    }

    shader_records = kmalloc(exec->shader_record_size, GFP_KERNEL);
    if (!shader_records) {
        ret = -ENOMEM;
        goto err_free_binning;
    }

    uniforms = kmalloc(exec->uniform_size, GFP_KERNEL);
    if (!uniforms) {
        ret = -ENOMEM;
        goto err_free_shader;
    }

    if (copy_from_user(binning_cmd_list, exec->user_binning_cmd,
                       exec->binning_cmd_size)) {
        ret = -EFAULT;
        goto err_free_uniforms;
    }

    if (copy_from_user(shader_records, exec->user_shader_records,
                       exec->shader_record_size)) {
        ret = -EFAULT;
        goto err_free_uniforms;
    }

    if (copy_from_user(uniforms, exec->user_uniforms, exec->uniform_size)) {
        ret = -EFAULT;
        goto err_free_uniforms;
    }

    bo = kzalloc(sizeof(*bo), GFP_KERNEL);
    if (!bo) {
        ret = -ENOMEM;
        goto err_free_uniforms;
    }

    ret = drm_gem_object_init(dev, &bo->base, uniforms_offset);
    if (ret) {
        goto err_free_bo;
    }

    ret = vc4_validate_binning_command(dev, binning_cmd_list,
                                      shader_records, uniforms);
    if (ret) {
        goto err_uninit_gem;
    }

    ret = vc4_wait_for_previous_rendering(dev, exec);
    if (ret) {
        goto err_uninit_gem;
    }

    exec->bo = &bo->base;
    exec->binning_cmd_list = binning_cmd_list;
    exec->shader_records = shader_records;
    exec->uniforms = uniforms;

    return 0;

err_uninit_gem:
    drm_gem_object_uninit(&bo->base);
err_free_bo:
    kfree(bo);
err_free_uniforms:
    kfree(uniforms);
err_free_shader:
    kfree(shader_records);
err_free_binning:
    kfree(binning_cmd_list);
    return ret;
}

int vc4_get_binning_cmdlist(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    int ret;
    void *cmdlist, *shader_records;
    unsigned int cmdlist_offset, shader_records_offset, uniforms_offset;
    size_t cmdlist_size, shader_records_size, uniforms_size;

    cmdlist_size = exec->cmdlist_args->cmdlist_size;
    shader_records_size = exec->cmdlist_args->shader_records_size;
    uniforms_size = exec->cmdlist_args->uniforms_size;

    if (cmdlist_size > 4 * 1024 * 1024 || shader_records_size > 4 * 1024 * 1024 ||
        uniforms_size > 4 * 1024 * 1024)
        return -EINVAL;

    cmdlist_offset = 0;
    shader_records_offset = cmdlist_size;
    uniforms_offset = shader_records_offset + shader_records_size;

    cmdlist = kvmalloc(cmdlist_size, GFP_KERNEL);
    if (!cmdlist)
        return -ENOMEM;

    shader_records = kvmalloc(shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        kfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->cmdlist_args->cmdlist), cmdlist_size)) {
        ret = -EFAULT;
        goto fail;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->cmdlist_args->shader_records), shader_records_size)) {
        ret = -EFAULT;
        goto fail;
    }

    bo = vc4_bo_create(dev, cmdlist_size + shader_records_size + uniforms_size, 0, true);
    if (IS_ERR(bo)) {
        ret = PTR_ERR(bo);
        goto fail;
    }

    ret = vc4_bo_map(bo);
    if (ret)
        goto fail_bo;

    memcpy(bo->vaddr, cmdlist, cmdlist_size);
    memcpy(bo->vaddr + shader_records_offset, shader_records, shader_records_size);

    kfree(cmdlist);
    kfree(shader_records);

    ret = vc4_wait_for_space(dev, exec);
    if (ret)
        goto fail_bo;

    exec->bo = bo;

    return 0;

fail_bo:
    vc4_bo_unmap(bo);
    vc4_bo_unreference(bo);
fail:
    kfree(cmdlist);
    kfree(shader_records);
    return ret;
}
